example:
for...of 走可迭代协议，for...in 走可枚举键：

```js
const list = [10, 20]
for (const n of list) { /* 10, 20 */ }
for (const key in list) { /* "0", "1" */ }
Array.prototype.extra = 1
for (const key in list) { /* 还会走到 "extra" */ }
for (const n of list) { /* 仍是 10, 20 */ }
// for (const x of { a: 1 }) → TypeError：不可迭代
```
